const visual = {
  prepare: function (input) { return [{ kind: 'text', payload: 'u=0' }, { kind: 'text', payload: 'u=1/2' }, { kind: 'text', payload: 'u=1' }]; },
  render: function (input, metrics) {
    var w = input.viewport.widthDu, h = input.viewport.heightDu;
    return { schemaVersion: 1, sceneId: 'cal', revision: input.revision,
             viewBox: { x: 0, y: 0, width: w, height: h },
             paths: [{ id: 'axis', commands: visualSdk.axis({ x0: 60, y0: 160, x1: 300, y1: 160, ticks: 0 }) }],
             root: { type: 'group', children: [
               { type: 'path', pathId: 'axis', fill: '#26354a', stroke: { width: 2 } }, { type: 'label', contentId: metrics[2].contentId, anchor: { x: 60, y: 180 }, hAlign: 'center', vAlign: 'top', color: '#26354a' }, { type: 'label', contentId: metrics[1].contentId, anchor: { x: 180, y: 180 }, hAlign: 'center', vAlign: 'top', color: '#26354a' }, { type: 'label', contentId: metrics[0].contentId, anchor: { x: 300, y: 180 }, hAlign: 'center', vAlign: 'top', color: '#26354a' } ] } };
  },
};
